"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[6555],{14841:e=>{e.exports=JSON.parse('{"functions":[{"name":"check","desc":"Intended to evaluate a player\'s ping/pong ratio and decide whether they are\\nrunning a modified client. Currently an empty stub \u2014 see the class note.","params":[{"name":"_player","desc":"player to evaluate","lua_type":"Player"}],"returns":[],"function_type":"static","source":{"line":48,"path":"src/Server/Features/Core/SecurityService.luau"}},{"name":"pong","desc":"Records one pong response from a player, incrementing their counter.","params":[{"name":"player","desc":"the responding player","lua_type":"Player"}],"returns":[],"function_type":"static","source":{"line":58,"path":"src/Server/Features/Core/SecurityService.luau"}},{"name":"getResponses","desc":"Returns the player\'s pong count so far, wrapped as a\\n`SECURITY_GET_RESPONSES` action. Zero for a player who has never responded.","params":[{"name":"player","desc":"player to query","lua_type":"Player"}],"returns":[{"desc":"","lua_type":"red.Action<number>"}],"function_type":"static","source":{"line":76,"path":"src/Server/Features/Core/SecurityService.luau"}},{"name":"removeResponses","desc":"Drops a player\'s response counter. Call on leave \u2014 the counter table is\\nkeyed by UserId and is never otherwise pruned.","params":[{"name":"userId","desc":"the departing player\'s UserId","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":92,"path":"src/Server/Features/Core/SecurityService.luau"}}],"properties":[],"types":[],"name":"SecurityService","desc":"Server half of the ping/pong anti-exploit heuristic. Pairs with the client\\n`SecurityController`.\\n\\nThe idea is a liveness challenge: the server pings a client, a legitimate\\nclient answers with a pong, and [SecurityService.pong] increments that\\nplayer\'s response counter. Comparing the response count against the number\\nof pings sent reveals a client that has stripped or stubbed the controller \u2014\\nan exploiter typically stops answering while continuing to play.\\n\\nCounters live in an in-memory [State] keyed by UserId and must be cleared\\nwith [SecurityService.removeResponses] when a player leaves, or the table\\nleaks across the server\'s lifetime.\\n\\n:::caution Incomplete\\nOnly the counting half exists. [SecurityService.check] is an empty stub, so\\nnothing currently evaluates the counts or acts on a suspicious ratio \u2014 no\\nkick, ban or flag is raised from here today. The honeypot in\\n`Handlers/Cheat.luau` is the only anti-exploit measure presently enforcing\\nanything.\\n:::\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Server"],"source":{"line":29,"path":"src/Server/Features/Core/SecurityService.luau"}}')}}]);